Rule.Source:
import sailpoint.object.ProvisioningPlan;
import sailpoint.object.ProvisioningPlan.AccountRequest;
import sailpoint.object.ProvisioningPlan.AttributeRequest;

if (plan != null && plan.getAccountRequests() != null) {
  for (AccountRequest request : plan.getAccountRequests()) {
    if (AccountRequest.Operation.Disable.equals(request.getOperation())) {
      request.add(new AttributeRequest("AC_NewParent", ProvisioningPlan.Operation.Set,
          "OU=Disabled Users,DC=example,DC=com"));
      log.info("Disable Moves OU: moving " + request.getNativeIdentity());
    }
  }
}
